mapper.select:
SELECT M.ProdName, M.ProdOption, M.ProdCode, M.State, M.Remark, M.RegistId, M.RegistName, CAST(M.RegistDate AS CHAR) AS RegistDate, M.ChangeId, M.ChangeName, CAST(M.ChangeDate AS CHAR) AS ChangeDate, P.ProdName AS MatchedProdName, P.ShopCode AS ShopCode, S.ShopName AS ShopName FROM shopwizard.tOrdProdCodeMatch M LEFT OUTER JOIN shopion.tPrdProd P ON P.ProdCode = M.ProdCode LEFT OUTER JOIN shopwizard.tCmpShop S ON S.ShopCode = P.ShopCode
ORDER BY M.RegistDate DESC, M.ProdName, M.ProdOption
LIMIT ${pPageOffset}, ${pPageSize}

mapper.insert:
INSERT INTO shopwizard.tOrdProdCodeMatch (
    ProdName, ProdOption, ProdCode, State, Remark, RegistId, RegistName, RegistDate
) VALUES (
    #{prodName}, #{prodOption}, #{prodCode}, 1, #{remark}, #{registId}, #{registName}, NOW()
)

mapper.update:
UPDATE shopwizard.tOrdProdCodeMatch SET
    ProdCode = #{prodCode}, State = 1, ChangeId = #{changeId}, ChangeName = #{changeName}, ChangeDate = NOW()
WHERE ProdName = #{prodName} AND ProdOption = #{prodOption}
